\set ON_ERROR_STOP on
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.expect_error(command text,expected text,label text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate<>expected then raise exception 'FAIL: % expected % got % (%)',label,expected,sqlstate,sqlerrm;end if;raise notice 'PASS: %',label;return;end;raise exception 'FAIL: % unexpectedly succeeded',label;end;$$;
insert into auth.users(id,email_confirmed_at) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,case when n=308 then null else now() end from generate_series(301,308)n;
insert into public.tenants(id,name,time_zone) values('60000000-0000-0000-0000-000000000001','Clock synthetic A','Europe/London'),('60000000-0000-0000-0000-000000000002','Clock synthetic B','UTC');
insert into public.tenant_memberships(tenant_id,user_id,display_name,role) select '60000000-0000-0000-0000-000000000001',('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Synthetic '||n,case n when 301 then 'owner' when 302 then 'admin' when 303 then 'manager' else 'employee' end from generate_series(301,308)n where n<>306;
insert into public.tenant_memberships values('60000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000306','Foreign owner','owner','active',now());
insert into public.agents(tenant_id,user_id,first_name,last_name,phone,created_by) select '60000000-0000-0000-0000-000000000001',('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Synthetic',n::text,'+447700900'||n,'00000000-0000-0000-0000-000000000301' from generate_series(301,305)n;
insert into public.agents(tenant_id,user_id,first_name,last_name,phone,created_by) values('60000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000306','Foreign','clock','+447700900306','00000000-0000-0000-0000-000000000306');
create function pg_temp.save(op text, extra jsonb default '{}',operation uuid default gen_random_uuid()) returns jsonb language sql as $$select public.save_time_clock('60000000-0000-0000-0000-000000000001',operation,jsonb_build_object('action',op)||extra)$$;
create function pg_temp.job(n text default 'Care') returns uuid language sql as $$select id from public.time_clock_jobs where name=n$$;
create function pg_temp.current_entry() returns jsonb language sql as $$select (public.read_time_clock('60000000-0000-0000-0000-000000000001')->'entry')$$;
create function pg_temp.change(op text,extra jsonb default '{}') returns jsonb language sql as $$select pg_temp.save(op,jsonb_build_object('entryId',pg_temp.current_entry()->>'id','revision',(pg_temp.current_entry()->>'revision')::integer)||extra)$$;
do $$declare tbl text;op text;begin foreach tbl in array array['time_clock_jobs','time_clock_entries','time_clock_breaks','time_clock_audit'] loop
 perform pg_temp.check_true((select relrowsecurity from pg_class where oid=('public.'||tbl)::regclass),'RLS on '||tbl);
 foreach op in array array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE'] loop
 perform pg_temp.check_true(not has_table_privilege('anon','public.'||tbl,op),'anon denied '||op||' '||tbl);
 if op<>'SELECT' then perform pg_temp.check_true(not has_table_privilege('authenticated','public.'||tbl,op),'browser denied '||op||' '||tbl);end if;
 end loop;end loop;end;$$;
select pg_temp.check_true(not has_table_privilege('authenticated','workforce_private.time_clock_operations','select'),'retry receipts inaccessible to browser');
select pg_temp.check_true(not has_function_privilege('anon','public.save_time_clock(uuid,uuid,jsonb)','execute'),'anonymous mutation RPC denied');
select pg_temp.check_true(not has_function_privilege('anon','public.read_time_clock(uuid,text,integer,date,date,jsonb)','execute'),'anonymous read RPC denied');
select pg_temp.check_true((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='workforce_private.save_time_clock(uuid,uuid,jsonb)'::regprocedure),'private mutation fixed definer path');
select pg_temp.check_true((select not prosecdef and provolatile='s' and proconfig @> array['search_path=""'] from pg_proc where oid='public.read_time_clock(uuid,text,integer,date,date,jsonb)'::regprocedure),'read snapshot retains invoker RLS');
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000301',false);
select pg_temp.save('create_job','{"name":"Care"}','70000000-0000-0000-0000-000000000001');
select pg_temp.check_true(pg_temp.save('create_job','{"name":"Care"}','70000000-0000-0000-0000-000000000001')->>'action'='create_job','same create retry returns acknowledged result');
select pg_temp.check_true((select count(*)=1 from public.time_clock_jobs),'create retry never duplicates job');
select pg_temp.check_true((select count(*)=1 from public.time_clock_audit),'create retry never duplicates audit');
select pg_temp.expect_error($q$select pg_temp.save('create_job','{"name":"Different"}','70000000-0000-0000-0000-000000000001')$q$,'40001','operation UUID cannot change payload');
select pg_temp.expect_error($q$select pg_temp.save('create_job','{"name":" care "}')$q$,'23505','active job names unique ignoring case and whitespace');
select pg_temp.save('create_job','{"name":"Unused"}');
select pg_temp.save('archive_job',jsonb_build_object('jobId',pg_temp.job('Unused'),'revision',1));
select pg_temp.check_true(not exists(select 1 from public.time_clock_jobs where name='Unused'),'unretained archived job hidden even from admin');
select pg_temp.expect_error($q$select pg_temp.save('clock_in',jsonb_build_object('jobId',pg_temp.job(),'started_at','2020-01-01T00:00:00Z'))$q$,'22023','client clock timestamps are rejected');
select pg_temp.expect_error($q$select public.save_time_clock('60000000-0000-0000-0000-000000000002',gen_random_uuid(),'{"action":"create_job","name":"Foreign"}')$q$,'42501','foreign company mutation denied');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000303',false);
select pg_temp.expect_error($q$select pg_temp.save('create_job','{"name":"Manager escalation"}')$q$,'42501','manager cannot create jobs');
select pg_temp.expect_error($q$select public.read_time_clock('60000000-0000-0000-0000-000000000001','attendance')$q$,'42501','manager cannot read team attendance');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000307',false);
select pg_temp.check_true(public.read_time_clock('60000000-0000-0000-0000-000000000001')->'agent'='null'::jsonb,'unlinked member receives explicit no-agent status');
select pg_temp.expect_error($q$select pg_temp.save('clock_in',jsonb_build_object('jobId',pg_temp.job()))$q$,'42501','unlinked member cannot clock in');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000308',false);
select pg_temp.expect_error($q$select public.read_time_clock('60000000-0000-0000-0000-000000000001')$q$,'42501','unconfirmed member cannot read clock');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000304',false);
select pg_temp.save('clock_in',jsonb_build_object('jobId',pg_temp.job()),'70000000-0000-0000-0000-000000000004');
select pg_temp.check_true((pg_temp.current_entry()->>'started_at')::timestamptz between statement_timestamp()-interval '5 seconds' and statement_timestamp(),'clock-in time assigned by database');
select pg_temp.check_true((pg_temp.current_entry()->>'revision')::integer=1,'clock-in begins revision one');
select pg_temp.check_true(pg_temp.save('clock_in',jsonb_build_object('jobId',pg_temp.job()),'70000000-0000-0000-0000-000000000004')->>'entryId'=pg_temp.current_entry()->>'id','clock-in retry returns identical entry');
select pg_temp.expect_error($q$select pg_temp.save('clock_in',jsonb_build_object('jobId',pg_temp.job()))$q$,'40001','different operation cannot create overlapping open entry');
select pg_temp.change('break_start','{"paid":false}');
select pg_temp.check_true((pg_temp.current_entry()->>'revision')::integer=2 and jsonb_array_length(pg_temp.current_entry()->'breaks')=1,'unpaid break starts and increments entry revision');
select pg_temp.expect_error($q$select pg_temp.change('break_start','{"paid":true}')$q$,'40001','overlapping paid or unpaid break rejected');
select pg_temp.expect_error($q$select pg_temp.change('break_end','{"revision":1}')$q$,'40001','stale break revision rejected');
select pg_temp.change('break_end');
select pg_temp.check_true((pg_temp.current_entry()->>'revision')::integer=3 and pg_temp.current_entry()->'breaks'->0->>'ended_at' is not null,'break end uses server time and increments revision');
select pg_temp.expect_error($q$select pg_temp.change('break_end')$q$,'40001','ending an already ended break rejected');
select pg_temp.change('break_start','{"paid":true}');
select pg_temp.current_entry()->>'id' as victim_id \gset
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000305',false);
select pg_temp.check_true((select count(*)=0 from public.time_clock_entries),'employee cannot read coworker entry');
select pg_temp.check_true((select count(*)=0 from public.time_clock_breaks),'employee cannot read coworker breaks');
select pg_temp.expect_error(format($q$select pg_temp.save('break_end',jsonb_build_object('entryId',%L,'revision',4))$q$,:'victim_id'),'P0002','known coworker entry UUID cannot be used for self clock action');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000301',false);
select pg_temp.save('archive_job',jsonb_build_object('jobId',pg_temp.job(),'revision',1));
select pg_temp.check_true((select status='archived' from public.time_clock_jobs where name='Care'),'retained job remains readable after archive');
reset role;update public.time_clock_entries set started_at=statement_timestamp()-interval '2 days' where ended_at is null;set role authenticated;
select pg_temp.check_true(jsonb_array_length(public.read_time_clock('60000000-0000-0000-0000-000000000001','attendance')->'entries')=1,'owner attendance includes coworker open entry across midnight');
select pg_temp.check_true(public.read_time_clock('60000000-0000-0000-0000-000000000001','attendance')->>'timeZone'='Europe/London','attendance exposes actual calendar filter time zone');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000304',false);
select pg_temp.check_true(pg_temp.current_entry()->>'job_name'='Care','job archive preserves current job name');
select pg_temp.change('break_end');
select pg_temp.change('break_start','{"paid":false}');
select pg_temp.change('clock_out');
select pg_temp.check_true(pg_temp.current_entry()='null'::jsonb,'clock-out ends current entry for archived job');
select pg_temp.check_true(not exists(select 1 from public.time_clock_breaks where ended_at is null),'clock-out ends its open break atomically');
select pg_temp.check_true(jsonb_array_length(public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets')->'entries')=1,'personal completed timesheet appears');
select pg_temp.expect_error($q$select pg_temp.save('clock_in',jsonb_build_object('jobId',pg_temp.job()))$q$,'40001','archived job cannot start another entry');
-- Suspension must reject even an already-acknowledged operation replay.
reset role;update public.tenant_memberships set status='suspended' where user_id='00000000-0000-0000-0000-000000000304';set role authenticated;
select pg_temp.expect_error($q$select pg_temp.save('clock_in',jsonb_build_object('jobId',pg_temp.job()),'70000000-0000-0000-0000-000000000004')$q$,'42501','authorization precedes idempotent receipt after suspension');
select pg_temp.check_true((select count(*)=0 from public.time_clock_entries),'suspension removes historical reads with existing token');
reset role;update public.tenant_memberships set status='active' where user_id='00000000-0000-0000-0000-000000000304';
-- Relinking an existing Auth member must not acknowledge the old agent's receipt.
set role authenticated;select pg_temp.job()::text as care_job_id \gset
reset role;update public.agents set user_id=null where phone='+447700900304';
insert into public.agents(tenant_id,user_id,first_name,last_name,phone,created_by) values('60000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000304','Replacement','Synthetic','+447700900340','00000000-0000-0000-0000-000000000301');
set role authenticated;
select pg_temp.expect_error(format($q$select pg_temp.save('clock_in',jsonb_build_object('jobId',%L),'70000000-0000-0000-0000-000000000004')$q$,:'care_job_id'),'42501','clock replay after relinking A to B cannot acknowledge A entry');
select pg_temp.check_true(jsonb_array_length(public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets')->'entries')=0,'relinked user cannot read earlier agent timesheets');
reset role;delete from public.agents where phone='+447700900340';update public.agents set user_id='00000000-0000-0000-0000-000000000304' where phone='+447700900304';
-- Synthetic retained history exercises calendar dates, ties and paid calculations.
insert into public.time_clock_entries(id,tenant_id,agent_id,job_id,agent_name,job_name,started_at,ended_at) select ('80000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'60000000-0000-0000-0000-000000000001',(select id from public.agents where phone='+447700900304'),(select id from public.time_clock_jobs where name='Care'),'Synthetic 304','Care',case when n=1 then '2026-10-24T23:00:00Z'::timestamptz else '2026-10-25T01:30:00.123456Z'::timestamptz end,'2026-10-25T03:30:00.123456Z' from generate_series(1,3)n;
insert into public.time_clock_breaks(tenant_id,entry_id,paid,started_at,ended_at) values('60000000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000003',true,'2026-10-25T01:40:00.123456Z','2026-10-25T01:50:00.123456Z'),('60000000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000003',false,'2026-10-25T02:00:00.123456Z','2026-10-25T02:15:00.123456Z');
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000304',false);
select pg_temp.check_true(jsonb_array_length(public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',100,'2026-10-25','2026-10-25')->'entries')=3,'company-date inclusive history includes 25-hour DST day boundary');
select pg_temp.check_true(jsonb_array_length(public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',100,'2026-10-24','2026-10-24')->'entries')=0,'UTC previous evening belongs to next company date');
select pg_temp.check_true(public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',1,'2026-10-25','2026-10-25')->'entries'->0->>'id'='80000000-0000-0000-0000-000000000003','keyset first tie ordered by descending identity');
select pg_temp.check_true(public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',1,'2026-10-25','2026-10-25',public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',1,'2026-10-25','2026-10-25')->'nextCursor')->'entries'->0->>'id'='80000000-0000-0000-0000-000000000002','keyset preserves microseconds and tie identity without duplicate');
select pg_temp.check_true((workforce_private.time_clock_entry_json('80000000-0000-0000-0000-000000000003',now())->>'paid_seconds')::numeric=6300,'tracked paid time subtracts unpaid break only');
select pg_temp.check_true((workforce_private.time_clock_entry_json('80000000-0000-0000-0000-000000000003',now())->>'unpaid_break_seconds')::numeric=900,'unpaid break total uses elapsed server instants');
select pg_temp.check_true(workforce_private.time_clock_day_start('2026-10-25','Europe/London')='2026-10-24T23:00:00Z' and workforce_private.time_clock_day_start('2026-10-26','Europe/London')='2026-10-26T00:00:00Z','first calendar instants span 25-hour rollback day');
select pg_temp.check_true(workforce_private.time_clock_day_start('2026-03-08','America/New_York')='2026-03-08T05:00:00Z' and workforce_private.time_clock_day_start('2026-03-09','America/New_York')='2026-03-09T04:00:00Z','first calendar instants span 23-hour spring day');
select pg_temp.check_true(workforce_private.time_clock_day_start('2011-12-30','Pacific/Apia')=workforce_private.time_clock_day_start('2011-12-31','Pacific/Apia'),'skipped company calendar day has an empty exact interval');
select pg_temp.check_true(workforce_private.time_clock_day_start('2026-11-01','America/Havana')='2026-11-01T04:00:00Z','Havana rollback chooses first midnight instead of later midnight');
reset role;update public.tenants set time_zone='America/Havana' where id='60000000-0000-0000-0000-000000000001';
insert into public.time_clock_entries(id,tenant_id,agent_id,job_id,agent_name,job_name,started_at,ended_at) select ('80000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'60000000-0000-0000-0000-000000000001',(select id from public.agents where phone='+447700900304'),(select id from public.time_clock_jobs where name='Care'),'Synthetic 304','Care',case when n=10 then '2026-11-01T04:30:00Z'::timestamptz else '2026-11-01T05:30:00Z'::timestamptz end,'2026-11-01T06:30:00Z' from generate_series(10,11)n;
set role authenticated;
select pg_temp.check_true(jsonb_array_length(public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',100,'2026-11-01','2026-11-01')->'entries')=2,'Havana date start includes both first and repeated midnight hours');
select pg_temp.check_true(jsonb_array_length(public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',100,'2026-10-31','2026-10-31')->'entries')=0,'Havana previous date end excludes first midnight hour of next day');
reset role;update public.tenants set time_zone='Europe/London' where id='60000000-0000-0000-0000-000000000001';set role authenticated;
select pg_temp.expect_error($q$select public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',101)$q$,'22023','history page bound enforced at database');
select pg_temp.expect_error($q$select public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',50,'infinity')$q$,'22023','infinite calendar filter rejected at database');
select pg_temp.expect_error($q$select public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',50,'2026-10-26','2026-10-25')$q$,'22023','reversed calendar range rejected at database');
select pg_temp.expect_error($q$select public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',1,'2026-10-26','2026-10-26',public.read_time_clock('60000000-0000-0000-0000-000000000001','timesheets',1,'2026-10-25','2026-10-25')->'nextCursor')$q$,'22023','cursor cannot change calendar scope');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000306',false);
select pg_temp.check_true((select count(*)=0 from public.time_clock_entries),'foreign company cannot read retained timesheets');
select pg_temp.expect_error($q$select public.read_time_clock('60000000-0000-0000-0000-000000000001')$q$,'42501','foreign tenant clock RPC rejects access');
reset role;
